// workers/backup-d1.ts -- Cron Trigger: 0 */6 * * *
// https://developers.cloudflare.com/d1/reference/backups/
// https://developers.cloudflare.com/workers/configuration/cron-triggers/

interface Env {
  DB: D1Database
  BACKUP_BUCKET: R2Bucket
  BACKUP_META: KVNamespace
}

export default {
  async scheduled(event: ScheduledEvent, env: Env, ctx: ExecutionContext) {
    const backupId = crypto.randomUUID()
    const timestamp = new Date().toISOString()

    // Get schema version from migrations table
    const version = await env.DB.prepare(
      "SELECT MAX(version) as v FROM _migrations"
    ).first<{ v: number }>()

    const tables = await env.DB.prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%'"
    ).all()

    const dumps: Record<string, unknown[]> = {}
    for (const t of tables.results) {
      dumps[t.name as string] = (await env.DB.prepare(`SELECT * FROM ${t.name}`).all()).results
    }

    const payload = JSON.stringify(dumps)
    const checksum = await sha256(payload)

    await env.BACKUP_BUCKET.put(`d1/${timestamp}/${backupId}.json`, payload, {
      customMetadata: { schemaVersion: String(version?.v), checksum, backupId },
    })

    await env.BACKUP_META.put(`d1:${backupId}`, JSON.stringify({
      backupId, timestamp, schemaVersion: version?.v, checksum,
      sizeBytes: payload.length, tables: Object.keys(dumps),
    }), { expirationTtl: 90 * 86400 })
  },
}

async function sha256(data: string): Promise<string> {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(data))
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('')
}

// CRITICAL: Durable Objects have NO native backup.
// https://developers.cloudflare.com/durable-objects/api/storage-api/

// Each DO class MUST implement /export:
export class GameSession extends DurableObject {
  async fetch(request: Request) {
    if (new URL(request.url).pathname === '/export') {
      const tables = [...await this.ctx.storage.sql.exec(
        "SELECT name FROM sqlite_master WHERE type='table'"
      )]
      const data: Record<string, unknown[]> = {}
      for (const t of tables) {
        data[t.name as string] = [...await this.ctx.storage.sql.exec(`SELECT * FROM ${t.name}`)]
      }
      return Response.json(data)
    }
    // ... normal logic
  }
}

// Backup worker iterates DO registry, calls /export, stores in R2

// Two restore paths:
// 1. D1 Time Travel (within 30d): wrangler d1 time-travel restore DB --timestamp=ISO
//    https://developers.cloudflare.com/d1/reference/time-travel/
// 2. R2 export restore (beyond 30d):

async function restoreFromR2(env: Env, backupId: string) {
  const meta = JSON.parse(await env.BACKUP_META.get(`d1:${backupId}`) ?? 'null')
  if (!meta) throw new Error(`Backup ${backupId} not found`)

  const obj = await env.BACKUP_BUCKET.get(`d1/${meta.timestamp}/${backupId}.json`)
  if (!obj) throw new Error('Backup artifact missing from R2')

  const payload = await obj.text()
  if (await sha256(payload) !== meta.checksum) throw new Error('Checksum mismatch')

  const dumps = JSON.parse(payload)
  for (const [table, rows] of Object.entries(dumps)) {
    await env.DB.prepare(`DELETE FROM ${table}`).run()
    for (const row of rows as Record<string, unknown>[]) {
      const cols = Object.keys(row)
      await env.DB.prepare(
        `INSERT INTO ${table} (${cols.join(', ')}) VALUES (${cols.map(() => '?').join(', ')})`
      ).bind(...Object.values(row)).run()
    }
  }
  // Run forward migrations if backup schema < current
}
